function toggleSubmenu(element,event){event.stopPropagation();var submenu=element.parentElement.querySelector(".nav__submenu");document.querySelectorAll(".nav__submenu").forEach(menu=>{if(menu!==submenu){menu.style.display="none"}});if(!submenu.style.display||submenu.style.display==="none"){submenu.style.display="block"}else{submenu.style.display="none"}}document.addEventListener("click",function(event){var isClickInsideMenu=event.target.closest(".nav__menu-opcion");if(!isClickInsideMenu){document.querySelectorAll(".nav__submenu").forEach(menu=>{menu.style.display="none"})}});